enum PackageSize       { SMALL, MEDIUM, LARGE }
enum CompartmentStatus { AVAILABLE, OCCUPIED }

class Compartment {
    private final String id;
    private final PackageSize size;
    private volatile CompartmentStatus status = CompartmentStatus.AVAILABLE;

    public Compartment(String id, PackageSize size) {
        this.id = id;
        this.size = size;
    }

    // Atomic occupy — returns false if already taken
    public synchronized boolean tryOccupy() {
        if (status == CompartmentStatus.AVAILABLE) {
            status = CompartmentStatus.OCCUPIED;
            return true;
        }
        return false;
    }

    public synchronized void release() {
        status = CompartmentStatus.AVAILABLE;
    }

    public boolean isFree() { return status == CompartmentStatus.AVAILABLE; }
    public String getId()   { return id; }
    public PackageSize getSize() { return size; }
}

class AccessToken {
    private final String code;
    private final String compartmentId;
    private final Instant createdAt;
    private final Duration ttl;

    public AccessToken(String compartmentId, Duration ttl) {
        this.code = generateSecureCode();
        this.compartmentId = compartmentId;
        this.createdAt = Instant.now();
        this.ttl = ttl;
    }

    public boolean isExpired() {
        return Instant.now().isAfter(createdAt.plus(ttl));
    }

    // 6-digit cryptographically random code
    private String generateSecureCode() {
        return String.format("%06d", new SecureRandom().nextInt(1_000_000));
    }

    public String getCode()           { return code; }
    public String getCompartmentId()  { return compartmentId; }
}

class LockerSystem {
    private final Map<PackageSize, List<Compartment>> compartments;
    private final ConcurrentHashMap<String, AccessToken> tokenMap = new ConcurrentHashMap<>();
    private final ReentrantLock depositLock = new ReentrantLock();
    private final Duration defaultTTL = Duration.ofDays(3);

    // Fallback order: try exact size, then larger
    private static final Map<PackageSize, List<PackageSize>> FALLBACK = Map.of(
        PackageSize.SMALL,  List.of(PackageSize.SMALL, PackageSize.MEDIUM, PackageSize.LARGE),
        PackageSize.MEDIUM, List.of(PackageSize.MEDIUM, PackageSize.LARGE),
        PackageSize.LARGE,  List.of(PackageSize.LARGE)
    );

    public LockerSystem(Map<PackageSize, List<Compartment>> compartments) {
        this.compartments = compartments;
        // Schedule cleanup every hour
        ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
        scheduler.scheduleAtFixedRate(this::cleanupExpired, 1, 1, TimeUnit.HOURS);
    }

    // ── deposit ─────────────────────────────
    public String deposit(PackageSize size) {
        depositLock.lock();
        try {
            // Try each fallback size
            for (PackageSize trySize : FALLBACK.get(size)) {
                List<Compartment> pool = compartments.getOrDefault(trySize, List.of());
                for (Compartment c : pool) {
                    if (c.tryOccupy()) {
                        AccessToken token = generateUniqueToken(c.getId());
                        tokenMap.put(token.getCode(), token);
                        return token.getCode();
                    }
                }
            }
            throw new NoCompartmentAvailableException(
                "No compartment available for size: " + size);
        } finally {
            depositLock.unlock();
        }
    }

    // ── pickup ──────────────────────────────
    public void pickup(String code) {
        if (code == null || code.isBlank())
            throw new IllegalArgumentException("Code required");

        AccessToken token = tokenMap.get(code);
        if (token == null)
            throw new InvalidCodeException("Code not found: " + code);

        if (token.isExpired()) {
            // Expired — release compartment, remove token, inform caller
            findCompartment(token.getCompartmentId()).release();
            tokenMap.remove(code);
            throw new CodeExpiredException("Code expired: " + code);
        }

        // Valid pickup
        findCompartment(token.getCompartmentId()).release();
        tokenMap.remove(code);
    }

    // ── cleanupExpired (background job) ─────
    public List<String> cleanupExpired() {
        List<String> rerouted = new ArrayList<>();
        tokenMap.forEach((code, token) -> {
            if (token.isExpired()) {
                findCompartment(token.getCompartmentId()).release();
                tokenMap.remove(code);
                rerouted.add(token.getCompartmentId());
            }
        });
        return rerouted; // these packages need rerouting
    }

    // ── Code collision handling ─────────────
    private AccessToken generateUniqueToken(String compartmentId) {
        for (int attempt = 0; attempt < 5; attempt++) {
            AccessToken token = new AccessToken(compartmentId, defaultTTL);
            if (!tokenMap.containsKey(token.getCode()))
                return token;
        }
        throw new RuntimeException("Failed to generate unique code after 5 attempts");
    }

    private Compartment findCompartment(String id) {
        return compartments.values().stream()
            .flatMap(List::stream)
            .filter(c -> c.getId().equals(id))
            .findFirst()
            .orElseThrow(() -> new IllegalStateException("Compartment not found: " + id));
    }

    public int getAvailable(PackageSize size) {
        return (int) compartments.getOrDefault(size, List.of()).stream()
            .filter(Compartment::isFree).count();
    }
}
